"""Reconstruct July 2023 sales from warehouse dispatches and cold-chain logs."""

import csv
import json
from datetime import datetime
from decimal import Decimal
from pathlib import Path


DATASET = Path("/app/dataset")


def _rows(filename: str):
    with (DATASET / filename).open(newline="") as file:
        yield from csv.DictReader(file)


def _number(value: str) -> Decimal:
    return Decimal(value.replace(",", "."))


def answer() -> int:
    products = {}
    safe_temperatures = {}
    for product in _rows("product_catalog.csv"):
        products[product["product_id"]] = product
        products[product["ean_code"]] = product  # One dispatch uses its EAN.
        safe_temperatures[product["storage_category"]] = _number(
            product["max_safe_temp_c"]
        )

    temperatures = {}
    for reading in _rows("temperature_logs.csv"):
        key = (datetime.fromisoformat(reading["timestamp"]), reading["zone"].title())
        temperatures[key] = _number(reading["temperature_c"])

    # Eight meat/frozen products left together at 03:17 during the only
    # temperature excursion. Both surrounding readings exceed their limits.
    disposal_time = datetime(2023, 7, 18, 3, 17)
    affected_zones = {"Meat", "Frozen"}
    for zone in affected_zones:
        for hour in (2, 4):
            reading_time = disposal_time.replace(hour=hour, minute=0)
            assert temperatures[(reading_time, zone)] > safe_temperatures[zone]

    revenue = Decimal(0)
    disposal_count = 0
    for dispatch in _rows("warehouse_dispatches.csv"):
        dispatched_at = datetime.fromisoformat(dispatch["timestamp"])
        if dispatched_at.year != 2023 or dispatched_at.month != 7:
            continue
        product = products[dispatch["product_id"]]
        value = int(dispatch["quantity"]) * _number(product["unit_price"])
        if dispatched_at == disposal_time and product["storage_category"] in affected_zones:
            disposal_count += 1
        else:
            revenue += value

    assert disposal_count == 8
    assert revenue == revenue.to_integral_value()
    return int(revenue)


if __name__ == "__main__":
    with open("/app/answer.json", "w") as file:
        json.dump(answer(), file)
